import { readFileSync } from "node:fs";

const expected = [
  ["2024-01-03", 0.02],
  ["2024-01-04", -0.02],
  ["2024-01-05", 0.030412],
];

function fail(message) {
  console.error(message);
  process.exit(1);
}

let plan;
try {
  plan = JSON.parse(readFileSync("returns.json", "utf8"));
} catch {
  fail("returns.json is missing or not valid JSON");
}

const rows = plan && plan.returns;
if (!Array.isArray(rows)) fail("returns must be an array");
if (rows.length !== expected.length) fail(`expected ${expected.length} rows, got ${rows.length}`);

for (let index = 0; index < expected.length; index += 1) {
  const row = rows[index] ?? {};
  if (row.date !== expected[index][0]) fail(`row ${index} has the wrong date: ${row.date}`);
  if (typeof row.return !== "number" || Math.abs(row.return - expected[index][1]) > 1e-6) {
    fail(`row ${index} has the wrong return: ${row.return}`);
  }
}

console.log("finance ok");
